#include <stdio.h>
int main(void) {
    char buf[5];
    FILE *fp = fopen("demo.txt", "w+");
    fputs("NEPAL\nKTM\n", fp);
    rewind(fp);
    while (fgets(buf, sizeof buf, fp) != NULL)
        printf("[%s]", buf);
    fclose(fp);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[4] = {5, 10, 15, 20}, x;
    FILE *fp = fopen("nums.bin", "w+b");
    fwrite(a, sizeof(int), 4, fp);
    fseek(fp, -2L * (long)sizeof(int), SEEK_END);
    fread(&x, sizeof x, 1, fp);
    fseek(fp, 0L, SEEK_CUR);
    fwrite(&x, sizeof x, 1, fp);
    rewind(fp);
    fread(a, sizeof(int), 4, fp);
    printf("x=%d pos=%ld last=%d\n", x, ftell(fp), a[3]);
    fclose(fp);
    return 0;
}

